#include <vector>
using namespace std;

class Solution {
public:
    long long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;
        if (k > n / 2) k = n - k;
        long long res = 1;
        for (int i = 1; i <= k; i++) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }

    long long findNthInteger(long long n, int k) {
        long long ans = 0;
        int rem_k = k;
        for (int bit = 60; bit >= 0; bit--) {
            if (rem_k == 0) break;
            long long ways_zero = comb(bit, rem_k);
            if (n > ways_zero) {
                ans |= (1LL << bit);
                n -= ways_zero;
                rem_k--;
            }
        }
        return ans;
    }
};

class Solution {
    private long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;
        if (k > n / 2) k = n - k;
        long res = 1;
        for (int i = 1; i <= k; i++) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }

    public long findNthInteger(long n, int k) {
        long ans = 0;
        int remK = k;
        for (int bit = 60; bit >= 0; bit--) {
            if (remK == 0) break;
            long waysZero = comb(bit, remK);
            if (n > waysZero) {
                ans |= (1L << bit);
                n -= waysZero;
                remK--;
            }
        }
        return ans;
    }
}

var findNthInteger = function(n, k) {
    function comb(N, K) {
        if (K < 0 || K > N) return 0n;
        if (K === 0 || K === N) return 1n;
        if (K > Math.floor(N / 2)) K = N - K;
        let res = 1n;
        for (let i = 1; i <= K; i++) {
            res = res * BigInt(N - i + 1) / BigInt(i);
        }
        return res;
    }
    let ans = 0n;
    let remK = k;
    let remN = BigInt(n);
    for (let bit = 60; bit >= 0; bit--) {
        if (remK === 0) break;
        const waysZero = comb(bit, remK);
        if (remN > waysZero) {
            ans |= (1n << BigInt(bit));
            remN -= waysZero;
            remK--;
        }
    }
    return Number(ans);
};
